def _wait_for_file_to_exist(s3: S3Client, obj: parse.ParseResult, sleep_time: int = 2) -> Any:
    bucket_name = obj.netloc
    object_key = obj.path.lstrip("/")
    while True:
        try:
            response = s3.client().head_object(Bucket=bucket_name, Key=object_key)
            return response
        except botocore.exceptions.ClientError as e:
            if e.response['Error']['Code'] == '404':
                print(f"File '{object_key}' not found in bucket '{bucket_name}'. Retrying in {sleep_time} seconds...")
