import inspect

class LambdaDataTransformRecipe:
    def __init__(self, _fn, _contains_is_last=False):
        self._fn = _fn
        self._contains_is_last = _contains_is_last

    def prepare_item(self, item_metadata, output_dir, is_last):
        signature = inspect.signature(self._fn)
        if 'is_last' in signature.parameters:
            kwargs = {'is_last': is_last} if self._contains_is_last else {}
            self._fn(item_metadata, output_dir, **kwargs)
        else:
            self._fn(item_metadata, output_dir)
```
